import { execFile } from 'child_process'
import { app, BrowserWindow, nativeImage } from 'electron'
import { existsSync, readdirSync, readFileSync, utimesSync, writeFileSync } from 'fs'
import { homedir } from 'os'
import { join } from 'path'
import { ACCENT, storedTheme } from './themeFile'

/** The icon in an accent colour (resources/icons/<accent>/, generated by scripts/accent-icons.py; the blue at the top). */
function iconsDirOf(accent: string): string {
	const root = app.isPackaged
		? join(process.resourcesPath, 'icons')
		: join(__dirname, '..', '..', 'resources', 'icons')
	return accent !== 'blue' && ACCENT.test(accent) && existsSync(join(root, accent)) ? join(root, accent) : root
}

function buildAppIcon(accent: string): Electron.NativeImage {
	const iconsDir = iconsDirOf(accent)

	const icon = nativeImage.createEmpty()

	if (!existsSync(iconsDir)) {
		console.warn('[icon] directory not found:', iconsDir)
		return icon
	}

	const files = readdirSync(iconsDir)
		.map(name => ({ name, match: /^(\d+)x\d+\.png$/i.exec(name) }))
		.filter((f): f is { name: string; match: RegExpExecArray } => f.match !== null)
		.map(f => ({ name: f.name, size: Number(f.match[1]) }))
		.sort((a, b) => a.size - b.size)

	for (const { name, size } of files) {
		const rep = nativeImage.createFromPath(join(iconsDir, name))
		if (rep.isEmpty()) continue
		icon.addRepresentation({
			scaleFactor: 1,
			width: size,
			height: size,
			buffer: rep.toPNG()
		})
	}

	if (icon.isEmpty()) {
		console.warn('[icon] no representations loaded from', iconsDir)
	}

	return icon
}

/**
 * The icon of the app's menu entry (Linux, the AppImage installed in the desktop's menu: its icons in
 * ~/.local/share/icons/hicolor/<size>/apps/, named after the app, hub-desktop.png, or
 * appimagekit_<hash>_hub-desktop.png by AppImageLauncher) in the accent: the files already there are
 * rewritten, none is added. The installed app only: the dev one leaves the menu alone.
 */
function updateMenuIcon(accent: string): void {
	if (!app.isPackaged || process.platform !== 'linux') return
	const hicolor = join(process.env.XDG_DATA_HOME || join(homedir(), '.local', 'share'), 'icons', 'hicolor')
	if (!existsSync(hicolor)) return
	const source = iconsDirOf(accent)
	let changed = false
	try {
		for (const size of readdirSync(hicolor)) {
			const apps = join(hicolor, size, 'apps')
			const own = join(source, `${size}.png`)
			if (!/^\d+x\d+$/.test(size) || !existsSync(apps) || !existsSync(own)) continue
			const body = readFileSync(own)
			for (const name of readdirSync(apps)) {
				if (!/(^|_)hub-desktop\.png$/.test(name)) continue
				const target = join(apps, name)
				if (readFileSync(target).equals(body)) continue
				writeFileSync(target, body)
				changed = true
			}
		}
		if (changed) {
			// the desktop's icon cache: stale once the folder changed, rebuilt when the tool is there
			utimesSync(hicolor, new Date(), new Date())
			if (existsSync(join(hicolor, 'icon-theme.cache'))) execFile('gtk-update-icon-cache', ['-q', '-f', '-t', hicolor], () => {})
		}
	} catch (e) {
		console.warn('[icon] menu icon not updated:', e)
	}
}

let accentShown = 'blue'
const changeListeners = new Set<() => void>()

/** Called when the icon changes (the tray redraws its own). */
export function onIconChange(listener: () => void): void {
	changeListeners.add(listener)
}

/** The app's icon, in the accent colour (a live binding: it changes with the accent; set by initIcon). */
export let appIcon = nativeImage.createEmpty()

/** The icon in the accent kept from last time: once ready, before any window (the data folder is known then). */
export function initIcon(): void {
	accentShown = storedTheme().accent
	appIcon = buildAppIcon(accentShown)
	// after an update, or a reinstall in the menu, the menu icon is blue again
	updateMenuIcon(accentShown)
}

/** The accent changed: the icon of every window and of the tray follows. */
export function setIconAccent(accent: string): void {
	if (accent === accentShown) return
	accentShown = accent
	appIcon = buildAppIcon(accent)
	for (const window of BrowserWindow.getAllWindows()) window.setIcon(appIcon)
	changeListeners.forEach(l => l())
	updateMenuIcon(accent)
}
